const locales: Record<Lang, Record<string, string>> = { en, "zh-CN": zhCN };

// Default language is zh-CN (primary user base writes Chinese).
// Returns "en" only when localStorage explicitly has "en" stored, so
// users who toggled keep their choice. Fresh visitors land on zh-CN.
export function getLang(): Lang {
  try {
    const stored = localStorage.getItem(LANG_KEY);
    return stored === "en" ? "en" : "zh-CN";
  } catch {
    return "zh-CN";
  }
}

export function setLang(lang: Lang): void {
  try {
    localStorage.setItem(LANG_KEY, lang);
  } catch {
    // ignore
  }
}

// hasI18nKey is the underlying lookup. Returns the localized string,
// or undefined when neither the active locale nor the en fallback
// has the key. Centralized so applyI18n can decide to keep the
// HTML's existing text instead of blanking it with the raw key.
function hasI18nKey(key: string): string | undefined {
  const lang = getLang();
  const locale = locales[lang] ?? en;
  return locale[key] ?? en[key];
}

export function t(key: string, params?: Record<string, string>): string {
  let str = hasI18nKey(key) ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      str = str.replace(new RegExp(`\\{\\{${k}\\}\\}`, "g"), v);
    }
  }
  return str;
}

export function applyI18n(): void {
  // When a key isn't defined in either locale, keep whatever the HTML
  // had as fallback (the static placeholder text inside the
  // [data-i18n] element). Previous behavior wrote the raw key
  // ("projects.title") into the DOM, which leaked the i18n key to
  // users any time we forgot to add the translation. Worse than no
  // i18n at all.
  document.querySelectorAll<HTMLElement>("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n")!;
    const value = hasI18nKey(key);
    if (value !== undefined) {
      el.textContent = value;
    }
  });
  document.querySelectorAll<HTMLElement>("[data-i18n-placeholder]").forEach((el) => {
    const key = el.getAttribute("data-i18n-placeholder")!;
    const value = hasI18nKey(key);
    if (value !== undefined) {
      (el as HTMLInputElement).placeholder = value;
    }
  });
  document.querySelectorAll<HTMLElement>("[data-i18n-title]").forEach((el) => {
    const key = el.getAttribute("data-i18n-title")!;
    const value = hasI18nKey(key);
    if (value !== undefined) {
      document.title = value;
    }
  });
  document.querySelectorAll<HTMLElement>("[data-i18n-tooltip]").forEach((el) => {
    const key = el.getAttribute("data-i18n-tooltip")!;
    const value = hasI18nKey(key);
    if (value !== undefined) {
      el.title = value;
    }
  });
  document.documentElement.lang = getLang();
}

// Inject a fixed top-right language toggle. Page-level utility,
// not a form field — anchored to body, not the brand banner. The
// previous "insert next to brand" placement made the toggle look
// like a separator between the brand banner and the auth card on
// login/register pages (per login—reg—language—switch.MD review).
export function injectLangToggle(): void {
  if (document.getElementById("langToggleBtn")) {
    return;
  }
  const btn = document.createElement("button");
  btn.id = "langToggleBtn";
  btn.type = "button";
  btn.className = "lang-toggle-btn";
  // Globe icon + the alternate language label (so the user sees
  // what they'll switch TO, not the current one). Lucide "globe"
  // path comes from lib/icons.ts.
  btn.innerHTML = `${iconHTML("globe", 14)}<span>${getLang() === "en" ? "中文" : "EN"}</span>`;
  btn.addEventListener("click", () => {
    setLang(getLang() === "en" ? "zh-CN" : "en");
    window.location.reload();
  });
  document.body.appendChild(btn);
}
